CREATE POLICY "audio read authenticated" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'audio');
CREATE POLICY "audio upload own folder" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'audio' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "audio delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'audio' AND (storage.foldername(name))[1] = auth.uid()::text);